import express from "express";
import { createServer as createViteServer } from "vite";
import path from "path";
import fs from "fs";

async function startServer() {
  const app = express();
  const PORT = 3000;
  
  app.use(express.json());
  
  // Request logging
  app.use((req, res, next) => {
    console.log(`${new Date().toISOString()} - ${req.method} ${req.url}`);
    next();
  });

  // Health check
  app.get("/api/health", (req, res) => {
    res.json({ status: "ok", timestamp: new Date().toISOString() });
  });

  // Client side runtime error reporting
  app.post("/api/client-error", (req, res) => {
    const errorDetails = `====================== CLIENT RUNTIME CRASH REPORT ======================\n` +
      `TIME: ${new Date().toISOString()}\n` +
      `MESSAGE: ${req.body.message}\n` +
      `TYPE: ${req.body.type || 'onload-error'}\n` +
      `SOURCE: ${req.body.source || 'unknown'}\n` +
      `LINE: ${req.body.lineno} COL: ${req.body.colno}\n` +
      `STACK: ${req.body.stack || 'No stack trace'}\n` +
      `=========================================================================\n`;
    
    console.error(errorDetails);
    try {
      fs.appendFileSync(path.join(process.cwd(), "client_errors.txt"), errorDetails);
    } catch (e) {
      console.error("Failed to write to client_errors.txt:", e);
    }
    res.json({ captured: true });
  });

  // Vite middleware for development (or as fallback if dist is missing)
  const isProduction = process.env.NODE_ENV === "production";
  const distPath = path.join(process.cwd(), "dist");
  const hasDist = fs.existsSync(distPath);

  if (!isProduction || !hasDist) {
    if (isProduction && !hasDist) {
      console.warn("Production mode detected but 'dist' directory is missing. Falling back to Vite middleware.");
    }
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
